import pandas as pd
import datetime
import json
from pathlib import Path

#   In getDay(), use "48h" or "2w" as second argument to get different horizons
#   The date specified in getDay() reffers to the one we want to predict.



# Code mainly generated by AI #
class schedule:
    def __init__ (self, dataDirectory: str | Path | None = None):
       
        self.timeLineDay: list = []
        self.timeLineTotal: dict = {}
        self.timeLineForecasts: dict[str, dict[pd.Timestamp, list[float]]] = {}
        self.isLoaded: bool = False

        if dataDirectory is None:
            dataDirectory = Path(__file__).resolve().parent.parent / "testDataForOptim"
        self.dataDirectory = Path(dataDirectory)

    def importJsonFile(self, filePath: str | Path):
        filePath = Path(filePath)
        with filePath.open("r", encoding="utf-8") as file:
            data = json.load(file)

        if not isinstance(data, dict):
            raise ValueError("The JSON file must contain an object")

        for horizon, timestampValues in data.items():
            if not isinstance(timestampValues, dict):
                raise ValueError(
                    f"Forecast horizon '{horizon}' must contain timestamp/value pairs"
                )

            valuesByDay: dict[pd.Timestamp, list[tuple[pd.Timestamp, float]]] = {}
            for timestamp, powerValue in timestampValues.items():
                timestampKey = pd.to_datetime(timestamp)
                if not isinstance(powerValue, (int, float)):
                    raise ValueError(
                        f"Power value for {timestamp} must be a number"
                    )

                dayKey = timestampKey.normalize()
                valuesByDay.setdefault(dayKey, []).append(
                    (timestampKey, powerValue)
                )

            horizonTimeline = self.timeLineForecasts.setdefault(horizon, {})
            for dayKey, timestampPowerPairs in valuesByDay.items():
                timestampPowerPairs.sort(key=lambda pair: pair[0])
                horizonTimeline[dayKey] = [
                    powerValue for _, powerValue in timestampPowerPairs
                ]

        for dayKey in sorted(
            {
                day
                for horizonTimeline in self.timeLineForecasts.values()
                for day in horizonTimeline
            }
        ):
            if "48h" in self.timeLineForecasts:
                if dayKey in self.timeLineForecasts["48h"]:
                    self.timeLineTotal[dayKey] = self.timeLineForecasts["48h"][dayKey]
                    continue

            for horizonTimeline in self.timeLineForecasts.values():
                if dayKey in horizonTimeline:
                    self.timeLineTotal[dayKey] = horizonTimeline[dayKey]
                    break

        self.isLoaded = True

    def importJsonFiles(self):
        if not self.dataDirectory.is_dir():
            raise FileNotFoundError(
                f"JSON data directory not found: {self.dataDirectory}"
            )

        for filePath in sorted(self.dataDirectory.glob("*.json")):
            self.importJsonFile(filePath)

    def requireLoaded(self):
        if not self.isLoaded:
            raise RuntimeError("No area data loaded, call importJsonFiles() first")

    def getHorizons(self) -> list[str]:
        self.requireLoaded()
        return list(self.timeLineForecasts.keys())

    def getDates(self, horizon: str | None = None) -> list[str]:
        self.requireLoaded()
        if horizon is None:
            days = self.timeLineTotal.keys()
        else:
            if horizon not in self.timeLineForecasts:
                raise KeyError(f"No forecast horizon found: {horizon}")
            days = self.timeLineForecasts[horizon].keys()
        return [day.strftime("%Y-%m-%d") for day in sorted(days)]

    def getDay(
        self,
        date: datetime.datetime | str | pd.Timestamp,
        horizon: str | None = None,
    ):
        self.requireLoaded()
        dateKey = pd.to_datetime(date).normalize()

        if horizon is not None:
            if horizon not in self.timeLineForecasts:
                raise KeyError(f"No forecast horizon found: {horizon}")
            if dateKey not in self.timeLineForecasts[horizon]:
                raise KeyError(f"No power timeline found for {date}")
            return self.timeLineForecasts[horizon][dateKey]

        if dateKey not in self.timeLineTotal:
            raise KeyError(f"No power timeline found for {date}")
        return self.timeLineTotal[dateKey]
